const SW_JS = "/**\n * ZENO Service Worker — 和の通信 (Harmonious Offline Cache)\n * Stale-while-revalidate for static shell; Network-first for dynamic state.\n */\n\nconst CACHE_NAME = \"zeno-v7-ultrabackyardloop\";\nconst STATIC_ASSETS = [\n  \"/\",\n  \"/index.html\",\n  \"/style.css\",\n  \"/app.js\",\n  \"/sound.js\",\n  \"/qrcode.js\",\n  \"/favicon.svg\",\n  \"/og.svg\",\n  \"/favicon.ico\",\n  \"/icons/icon-16.png\",\n  \"/icons/icon-32.png\",\n  \"/icons/icon-48.png\",\n  \"/icons/icon-192.png\",\n  \"/icons/icon-512.png\",\n  \"/icons/apple-touch-icon.png\",\n  \"/icons/icon-maskable-192.png\",\n  \"/icons/icon-maskable-512.png\",\n  \"/beacon.json\",\n  \"/manifest.webmanifest\"\n];\n\nself.addEventListener(\"install\", (event) => {\n  event.waitUntil(\n    caches.open(CACHE_NAME).then((cache) => {\n      return cache.addAll(STATIC_ASSETS);\n    }).then(() => self.skipWaiting())\n  );\n});\n\nself.addEventListener(\"activate\", (event) => {\n  event.waitUntil(\n    caches.keys().then((keys) => {\n      return Promise.all(\n        keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))\n      );\n    }).then(() => self.clients.claim())\n  );\n});\n\nself.addEventListener(\"fetch\", (event) => {\n  const url = new URL(event.request.url);\n\n  // Skip non-GET and cross-origin external API requests\n  if (event.request.method !== \"GET\" || url.origin !== self.location.origin) {\n    return;\n  }\n\n  // Network-first for HTML, Stale-while-revalidate for assets\n  if (event.request.headers.get(\"accept\")?.includes(\"text/html\")) {\n    event.respondWith(\n      fetch(event.request)\n        .then((response) => {\n          const cloned = response.clone();\n          caches.open(CACHE_NAME).then((cache) => cache.put(event.request, cloned));\n          return response;\n        })\n        .catch(() => caches.match(event.request).then((res) => res || caches.match(\"/\")))\n    );\n    return;\n  }\n\n  event.respondWith(\n    caches.match(event.request).then((cached) => {\n      const fetchPromise = fetch(event.request).then((networkResponse) => {\n        if (networkResponse && networkResponse.status === 200) {\n          const cloned = networkResponse.clone();\n          caches.open(CACHE_NAME).then((cache) => cache.put(event.request, cloned));\n        }\n        return networkResponse;\n      }).catch(() => cached);\n\n      return cached || fetchPromise;\n    })\n  );\n});\n";
