function evaluateFokenInvoice(invoice) {
  const invId = invoice.invoiceId || "unknown";

  const required = ["invoiceId", "version", "contributor", "work", "artifact", "valuation", "ipAssignment"];
  for (const f of required) {
    if (!invoice[f]) {
      return { invoiceId: invId, verdict: "FAIL", reason: "missing field '" + f + "'" };
    }
  }

  if (!/^0x[0-9a-fA-F]{40}$/.test(invoice.contributor)) {
    return { invoiceId: invId, verdict: "FAIL", reason: "invalid contributor address format" };
  }

  if (!invoice.artifact.provenanceHash?.startsWith("sha256://")) {
    return { invoiceId: invId, verdict: "FAIL", reason: "artifact provenance must start with sha256://" };
  }

  const fokens = invoice.valuation.selfAssessedFokens;
  if (typeof fokens !== "number" || fokens <= 0 || !Number.isInteger(fokens)) {
    return { invoiceId: invId, verdict: "FAIL", reason: "selfAssessedFokens must be a positive integer" };
  }

  const ip = invoice.ipAssignment;
  if (!ip.statement?.includes("IRREVOCABLE ASSIGNMENT") || !ip.signature?.startsWith("0x")) {
    return { invoiceId: invId, verdict: "FAIL", reason: "missing/unsigned IP assignment — no IP, no mint" };
  }

  const nu = invoice.netUtility;
  if (!nu || typeof nu.futureWorkAvoidedHours !== "number") {
    return { invoiceId: invId, verdict: "REVIEW", reason: "missing/invalid netUtility figures" };
  }

  const net = nu.futureWorkAvoidedHours - (nu.workAddedHours + 1.5 * nu.maintenanceDebtHours);
  if (net <= 0) {
    return {
      invoiceId: invId,
      verdict: "FAIL",
      reason: "net-negative utility (" + net + "): work added exceeds future work avoided",
      netUtility: net,
    };
  }

  return {
    invoiceId: invId,
    verdict: "PASS",
    reason: "eligible for human vote (net utility = " + net + ")",
    netUtility: net,
  };
}

// ---------------------------------------------------------------------------
// Google Wallet generic pass (RFC-006)
// Mirrors apps/wallet/google_wallet.py — keep the two in sync.
// ---------------------------------------------------------------------------

const GW_CLASS_SUFFIX = "zeno_aeon_pay";
const GW_SAVE_PREFIX = "https://pay.google.com/gp/v/save/";
const GW_MICRO_YEN = 1000000;
const GW_MAX_JWT_LEN = 1800;

function gwJson(body, status) {
  return new Response(JSON.stringify(body, null, 2), {
    status: status || 200,
    headers: {
      ...COMMON_HEADERS,
      "content-type": "application/json; charset=utf-8",
      "cache-control": "no-store",
    },
  });
}

function gwB64Url(bytes) {
  let binary = "";
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunk));
  }
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function gwB64UrlText(text) {
  return gwB64Url(new TextEncoder().encode(text));
}

function gwSanitizeObjectId(accountId) {
  const cleaned = String(accountId).trim().replace(/[^A-Za-z0-9._-]/g, "_").replace(/^[._-]+|[._-]+$/g, "");
  return (cleaned || "account").slice(0, 60);
}

function gwLocalized(value) {
  return { defaultValue: { language: "en-US", value: value } };
}

function gwBuildClass(issuerId) {
  return {
    id: issuerId + "." + GW_CLASS_SUFFIX,
    enableSmartTap: true,
  };
}

function gwBuildObject(issuerId, accountId, holder, balanceUjpy) {
  const yen = balanceUjpy / GW_MICRO_YEN;
  const headerValue = Number.isInteger(yen)
    ? "¥" + yen.toLocaleString("en-US")
    : "¥" + yen.toFixed(2);
  return {
    id: issuerId + ".zeno_" + gwSanitizeObjectId(accountId),
    classId: issuerId + "." + GW_CLASS_SUFFIX,
    hexBackgroundColor: "#07080b",
    cardTitle: gwLocalized("ZENO 銭"),
    header: gwLocalized(headerValue),
    subheader: gwLocalized("Mobile PASMO · FeliCa NFC-F"),
    logo: { sourceUri: { uri: "https://zeno.vaked.dev/icons/icon-192.png" } },
    barcode: {
      type: "QR_CODE",
      value: "zeno://pay/" + accountId + "?bank=ZENO",
      alternateText: accountId,
    },
    textModulesData: [
      { id: "holder", header: "HOLDER", body: holder },
      { id: "rails", header: "RAILS", body: "FeliCa NFC-F · Kintsugi" },
    ],
  };
}

function gwBuildClaims(issuerEmail, issuerId, accountId, holder, balanceUjpy) {
  return {
    iss: issuerEmail,
    aud: "google",
    typ: "savetowallet",
    iat: Math.floor(Date.now() / 1000),
    origins: ["https://zeno.vaked.dev"],
    payload: {
      genericClasses: [gwBuildClass(issuerId)],
      genericObjects: [gwBuildObject(issuerId, accountId, holder, balanceUjpy)],
    },
  };
}

async function gwSignRs256(claims, privateKeyPem) {
  const der = privateKeyPem
    .replace(/-----BEGIN[^-]+-----/g, "")
    .replace(/-----END[^-]+-----/g, "")
    .replace(/\s+/g, "");
  const raw = atob(der);
  const keyBytes = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) keyBytes[i] = raw.charCodeAt(i);

  const key = await crypto.subtle.importKey(
    "pkcs8",
    keyBytes,
    { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" },
    false,
    ["sign"],
  );

  const header = gwB64UrlText(JSON.stringify({ alg: "RS256", typ: "JWT" }));
  const payload = gwB64UrlText(JSON.stringify(claims));
  const signingInput = header + "." + payload;
  const signature = new Uint8Array(
    await crypto.subtle.sign(
      "RSASSA-PKCS1-v1_5",
      key,
      new TextEncoder().encode(signingInput),
    ),
  );
  return signingInput + "." + gwB64Url(signature);
}

async function googleWalletPass(request, env) {
  const url = new URL(request.url);
  const accountId = url.searchParams.get("account") || "cnt_0x71c8";
  const holder = url.searchParams.get("holder") || "8b-is Crew";
  const rawBalance = url.searchParams.get("balance_ujpy");

  let balanceUjpy = 4820 * GW_MICRO_YEN;
  if (rawBalance !== null) {
    balanceUjpy = Number(rawBalance);
    if (!Number.isSafeInteger(balanceUjpy) || balanceUjpy < 0) {
      return gwJson({ error: "invalid_balance", detail: "balance_ujpy must be a non-negative safe integer" }, 400);
    }
  }

  const issuerId = env.GOOGLE_WALLET_ISSUER_ID || null;
  let serviceAccount = null;
  if (env.GOOGLE_WALLET_SA_JSON) {
    try {
      serviceAccount = typeof env.GOOGLE_WALLET_SA_JSON === "string"
        ? JSON.parse(env.GOOGLE_WALLET_SA_JSON)
        : env.GOOGLE_WALLET_SA_JSON;
    } catch (e) {
      return gwJson({ error: "invalid_service_account", detail: "GOOGLE_WALLET_SA_JSON is not valid JSON" }, 500);
    }
  }

  const missing = [];
  if (!issuerId) missing.push("GOOGLE_WALLET_ISSUER_ID");
  if (!serviceAccount || !serviceAccount.client_email || !serviceAccount.private_key) {
    missing.push("GOOGLE_WALLET_SA_JSON");
  }

  if (missing.length > 0) {
    const placeholderIssuer = issuerId || "0";
    return gwJson({
      mode: "unconfigured",
      missing: missing,
      claims: gwBuildClaims(
        (serviceAccount && serviceAccount.client_email) || "unconfigured@example.invalid",
        placeholderIssuer,
        accountId,
        holder,
        balanceUjpy,
      ),
    });
  }

  const claims = gwBuildClaims(serviceAccount.client_email, issuerId, accountId, holder, balanceUjpy);
  const jwt = await gwSignRs256(claims, serviceAccount.private_key);

  return gwJson({
    mode: "live",
    claims: claims,
    jwt: jwt,
    saveUrl: GW_SAVE_PREFIX + jwt,
    jwtLength: jwt.length,
    overLengthLimit: jwt.length > GW_MAX_JWT_LEN,
  });
}
